source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    frames = []
    frame_cells = set()
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        border = {(r, c) for r in range(r0, r1+1) for c in range(c0, c1+1)
                  if r in (r0, r1) or c in (c0, c1)}
        if set(pts) == border:
            frames.append((color, r0, r1, c0, c1))
            frame_cells.update(border)
    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r, c) not in frame_cells:
                counts[color] = counts.get(color, 0) + 1
    out = [[0]*w for _ in range(h)]
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color
    for color, r0, r1, c0, c1 in frames:
        inner = [(r, c) for r in range(r0+1, r1) for c in range(c0+1, c1)
                 if (r+c) % 2 == (r0+c0+2) % 2]
        # The matching marker color has as many scattered pixels as checkerboard cells.
        marker = next((v for v, n in counts.items() if n == len(inner)), None)
        if marker is not None:
            for r, c in inner:
                if (r+c) % 2 == (r0+c0+2) % 2:
                    out[r][c] = marker
    return out
'''
